CREATE OR REPLACE FUNCTION public.my_space() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT jsonb_build_object('joined',p.created_at,'pseudonym',p.pseudonym,'posts',(SELECT count(*) FROM public.posts WHERE author_id=auth.uid()),'comments',(SELECT count(*) FROM public.comments WHERE author_id=auth.uid()),'support',(SELECT count(*) FROM public.reactions r JOIN public.posts s ON s.id=r.post_id WHERE s.author_id=auth.uid()),'my_posts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'body',s.body,'community',s.community,'pseudonym',s.pseudonym,'post_type',s.post_type,'progress',s.progress,'created_at',s.created_at,'expires_at',s.expires_at,'removed',s.admin_removed OR s.author_deleted OR s.is_deleted) ORDER BY s.created_at DESC),'[]'::jsonb) FROM public.posts s WHERE s.author_id=auth.uid()),'my_comments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'post_id',c.post_id,'body',c.body,'created_at',c.created_at,'removed',c.admin_removed OR c.is_deleted) ORDER BY c.created_at DESC),'[]'::jsonb) FROM public.comments c WHERE c.author_id=auth.uid()),'supported',(SELECT coalesce(jsonb_agg(DISTINCT r.post_id),'[]'::jsonb) FROM public.reactions r JOIN public.posts s ON s.id=r.post_id WHERE r.user_id=auth.uid() AND NOT(s.is_deleted OR s.author_deleted OR s.admin_removed))) INTO result FROM public.profiles p WHERE p.id=auth.uid(); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.owner_post_action(_id uuid,_action text,_progress text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_id AND author_id=auth.uid() AND NOT(admin_removed OR author_deleted OR is_deleted)) THEN RAISE EXCEPTION 'Post unavailable'; END IF; IF _action='delete' THEN UPDATE public.posts SET author_deleted=true WHERE id=_id; ELSIF _action='progress' AND _progress IN ('carrying','working','let_go') THEN UPDATE public.posts SET progress=_progress WHERE id=_id; ELSE RAISE EXCEPTION 'Invalid action'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_open_user(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),'view_user_detail','profile',_id); SELECT jsonb_build_object('profile',to_jsonb(p),'posts',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM public.posts s WHERE s.author_id=_id),'comments',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) FROM public.comments c WHERE c.author_id=_id),'reactions',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.reactions r WHERE r.user_id=_id),'reports',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.reports r WHERE r.reporter_id=_id),'conversations',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status)),'[]'::jsonb) FROM public.conversations c WHERE c.sender_id=_id OR c.recipient_id=_id)) INTO result FROM public.profiles p WHERE p.id=_id; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.admin_open_conversation(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),'view_conversation','conversation',_id); SELECT jsonb_build_object('id',c.id,'status',c.status,'sender',jsonb_build_object('pseudonym',a.pseudonym,'email',a.email),'recipient',jsonb_build_object('pseudonym',b.pseudonym,'email',b.email),'messages',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',m.body,'created_at',m.created_at,'sender',CASE WHEN m.sender_id=c.sender_id THEN a.pseudonym ELSE b.pseudonym END,'removed',m.admin_removed) ORDER BY m.created_at),'[]'::jsonb) FROM public.messages m WHERE m.conversation_id=c.id)) INTO result FROM public.conversations c LEFT JOIN public.profiles a ON a.id=c.sender_id LEFT JOIN public.profiles b ON b.id=c.recipient_id WHERE c.id=_id; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.admin_list_conversations() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'created_at',c.created_at,'sender',jsonb_build_object('pseudonym',a.pseudonym,'email',a.email),'recipient',jsonb_build_object('pseudonym',b.pseudonym,'email',b.email)) ORDER BY c.updated_at DESC),'[]'::jsonb) FROM public.conversations c LEFT JOIN public.profiles a ON a.id=c.sender_id LEFT JOIN public.profiles b ON b.id=c.recipient_id); END $$;
CREATE OR REPLACE FUNCTION public.admin_moderate(_kind text,_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _kind='conversation' AND _action='close' THEN UPDATE public.conversations SET status='closed' WHERE id=_id; ELSIF _kind='message' AND _action='remove' THEN UPDATE public.messages SET admin_removed=true WHERE id=_id; ELSIF _kind='post' AND _action='remove' THEN UPDATE public.posts SET admin_removed=true WHERE id=_id; ELSIF _kind='comment' AND _action='remove' THEN UPDATE public.comments SET admin_removed=true WHERE id=_id; ELSIF _kind='profile' AND _action IN ('ban','unban') THEN UPDATE public.profiles SET is_banned=(_action='ban') WHERE id=_id; ELSE RAISE EXCEPTION 'Invalid moderation action'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),_action,_kind,_id); END $$;
REVOKE ALL ON FUNCTION public.my_space(),public.owner_post_action(uuid,text,text),public.admin_open_user(uuid),public.admin_open_conversation(uuid),public.admin_list_conversations(),public.admin_moderate(text,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.my_space(),public.owner_post_action(uuid,text,text),public.admin_open_user(uuid),public.admin_open_conversation(uuid),public.admin_list_conversations(),public.admin_moderate(text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.admin_removed AND NOT NEW.admin_removed THEN RAISE EXCEPTION 'Cannot restore moderation removal'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND NEW.admin_removed IS DISTINCT FROM OLD.admin_removed THEN RAISE EXCEPTION 'Admin only'; END IF; IF TG_TABLE_NAME='posts' THEN IF OLD.author_deleted AND NOT NEW.author_deleted THEN RAISE EXCEPTION 'Cannot restore deleted post'; END IF; IF NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.pseudonym IS DISTINCT FROM OLD.pseudonym OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN RAISE EXCEPTION 'Protected fields'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND (NEW.title IS DISTINCT FROM OLD.title OR NEW.body IS DISTINCT FROM OLD.body OR NEW.community IS DISTINCT FROM OLD.community OR NEW.post_type IS DISTINCT FROM OLD.post_type OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN RAISE EXCEPTION 'Protected fields'; END IF; ELSE IF NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.pseudonym IS DISTINCT FROM OLD.pseudonym OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN RAISE EXCEPTION 'Protected fields'; END IF; END IF; RETURN NEW; END $$;
CREATE POLICY "authors read own comments" ON public.comments FOR SELECT TO authenticated USING(author_id=auth.uid());